import{_ as h,o as t,c,a2 as i}from"./chunks/framework.BBd5PKnH.js";const a="/dev-notes/assets/Screenshot%202026-10-04%20at%2023.52.16.BJlzIB6G.png",p=JSON.parse('{"title":"Cloud vs On-Premises","description":"","frontmatter":{"title":"Cloud vs On-Premises","date":"2026-10-04T00:00:00.000Z"},"headers":[],"relativePath":"notes/cloud_vs_on_premises.md","filePath":"notes/cloud_vs_on_premises.md"}'),o={name:"notes/cloud_vs_on_premises.md"};function g(u,n,e,r,l,s){return t(),c("div",null,[...n[0]||(n[0]=[i('<p><img src="'+a+'" alt="Dải lựa chọn tự làm vs thuê ngoài"></p><p>Đoạn này mở đầu một chủ đề mới: <strong>tự làm hay thuê ngoài</strong> (build or buy), áp dụng cho phần mềm và hạ tầng.</p><h2 id="nguyen-tac-chung-cai-gi-la-loi-the-cot-loi-thi-tu-lam" tabindex="-1">Nguyên tắc chung: cái gì là lợi thế cốt lõi thì tự làm <a class="header-anchor" href="#nguyen-tac-chung-cai-gi-la-loi-the-cot-loi-thi-tu-lam" aria-label="Permalink to &quot;Nguyên tắc chung: cái gì là lợi thế cốt lõi thì tự làm&quot;">​</a></h2><p>Câu hỏi này thực chất là về ưu tiên kinh doanh. Quy tắc phổ biến: thứ gì là <strong>năng lực cốt lõi</strong> hoặc <strong>lợi thế cạnh tranh</strong> của công ty thì tự làm. Thứ gì là việc thông thường, ai cũng cần, không tạo khác biệt thì để nhà cung cấp lo.</p><p>Ví dụ cực đoan của tác giả: gần như không công ty phần mềm nào tự sản xuất chip CPU, vì mua của Intel hay AMD rẻ hơn nhiều. Chip quan trọng, nhưng không phải thứ giúp họ thắng đối thủ.</p><p>Ví dụ gần hơn: một công ty fintech nên tự viết logic chấm điểm tín dụng, vì đó là bí quyết kiếm tiền của họ. Nhưng hệ thống gửi email thì cứ dùng SendGrid hay Amazon SES, tự viết mail server chẳng giúp họ hơn ai.</p><h2 id="hai-cau-hoi-ai-viet-phan-mem-ai-van-hanh-no" tabindex="-1">Hai câu hỏi: ai viết phần mềm, ai vận hành nó <a class="header-anchor" href="#hai-cau-hoi-ai-viet-phan-mem-ai-van-hanh-no" aria-label="Permalink to &quot;Hai câu hỏi: ai viết phần mềm, ai vận hành nó&quot;">​</a></h2><p>Với phần mềm, có hai quyết định tách biệt: <strong>ai viết code</strong> và <strong>ai chạy, bảo trì nó</strong>. Hình 1-2 vẽ ba điểm trên một dải liên tục. Lấy Redis làm ví dụ cho dễ hình dung:</p><p><strong>Bên trái: tự viết, tự vận hành.</strong> Ví dụ code ứng dụng FastAPI của bạn. Team bạn viết, team bạn deploy, sập thì team bạn sửa lúc 2 giờ sáng. Bạn có toàn quyền kiểm soát, nhưng tốn nhiều công sức nhất.</p><p><strong>Ở giữa: dùng phần mềm có sẵn, nhưng tự vận hành (self-host).</strong> Ví dụ bạn lấy Redis (mã nguồn mở, không phải tự viết) rồi tự chạy trong Docker trên một máy EC2. Bạn không phải viết database, nhưng phải tự lo cài đặt, cấu hình, nâng cấp phiên bản, backup, theo dõi RAM đầy, và tự xử lý khi máy chết.</p><p>Máy đó có thể là server vật lý của công ty (gọi là <em>on-premises</em>, kể cả khi nó nằm trong datacenter thuê ngoài chứ không phải văn phòng công ty), hoặc một máy ảo trên cloud như EC2 (gọi là <em>IaaS</em>, hạ tầng như một dịch vụ). Dù là cái nào, việc vận hành phần mềm vẫn là của bạn.</p><p><strong>Bên phải: dùng phần mềm có sẵn, để nhà cung cấp vận hành (cloud service/SaaS).</strong> Ví dụ dùng Amazon ElastiCache for Redis. Bạn chỉ nhận một địa chỉ để kết nối, còn AWS lo cài đặt, vá lỗi, backup, chuyển sang máy dự phòng khi máy chính hỏng. Ít việc nhất, nhưng cũng ít quyền kiểm soát nhất: bạn không chỉnh được mọi cấu hình, không chọn được thời điểm nâng cấp tùy ý, và phải chấp nhận giá của họ.</p><p>Mũi tên dưới hình tóm tắt sự đánh đổi: đi về bên trái thì <strong>kiểm soát nhiều hơn nhưng tốn đầu tư hơn</strong>, đi về bên phải thì <strong>ít kiểm soát hơn nhưng đầu tư ít hơn</strong>.</p><p>Ngoài ba điểm đó còn có nhiều điểm khác ở giữa, ví dụ lấy một phần mềm mã nguồn mở rồi sửa code cho hợp nhu cầu riêng và tự chạy bản đã sửa.</p><h2 id="cau-hoi-lien-quan-deploy-bang-cach-nao" tabindex="-1">Câu hỏi liên quan: deploy bằng cách nào <a class="header-anchor" href="#cau-hoi-lien-quan-deploy-bang-cach-nao" aria-label="Permalink to &quot;Câu hỏi liên quan: deploy bằng cách nào&quot;">​</a></h2><p>Đoạn cuối nhắc tới một câu hỏi khác: <strong>triển khai ở đâu và bằng công cụ gì</strong>, ví dụ chạy trên cloud hay server riêng, có dùng Kubernetes hay không. Bạn đang làm với ECS/EKS chính là đang ở trong câu hỏi này. Nhưng tác giả nói sách sẽ không đi sâu vào phần công cụ deploy, vì nó ít ảnh hưởng tới kiến trúc dữ liệu hơn những yếu tố khác.</p><h2 id="tom-lai" tabindex="-1">Tóm lại <a class="header-anchor" href="#tom-lai" aria-label="Permalink to &quot;Tóm lại&quot;">​</a></h2><p>Đoạn này đặt nền cho phần tiếp theo: mỗi lựa chọn trên dải từ &quot;tự làm hết&quot; tới &quot;thuê hết&quot; đều có đánh đổi giữa quyền kiểm soát và chi phí công sức, và nên chọn dựa trên việc thứ đó có phải là lợi thế cốt lõi của công ty hay không. Các trang sau trong sách sẽ phân tích kỹ ưu nhược điểm của cloud so với self-host.</p><h2 id="downside-cua-cloud-services" tabindex="-1">Downside của cloud services <a class="header-anchor" href="#downside-cua-cloud-services" aria-label="Permalink to &quot;Downside của cloud services&quot;">​</a></h2><p>Đoạn này là nửa còn lại của phần so sánh: sau khi nói về lợi ích, tác giả liệt kê <strong>nhược điểm lớn nhất của cloud service: bạn không kiểm soát được nó</strong>. Mình đi qua từng ý với ví dụ cụ thể.</p><h2 id="_1-thieu-tinh-nang-thi-chi-biet-xin" tabindex="-1">1. Thiếu tính năng thì chỉ biết xin <a class="header-anchor" href="#_1-thieu-tinh-nang-thi-chi-biet-xin" aria-label="Permalink to &quot;1. Thiếu tính năng thì chỉ biết xin&quot;">​</a></h2><p>Nếu dịch vụ thiếu một tính năng bạn cần, bạn chỉ có thể gửi yêu cầu lịch sự cho nhà cung cấp và chờ. Bạn không tự thêm vào được.</p><p>Ví dụ: bạn dùng ElastiCache và cần một module Redis đặc biệt (như RedisJSON phiên bản mới). Tự host thì cài vào là xong. Trên dịch vụ quản lý sẵn, nếu AWS chưa hỗ trợ module đó thì bạn đành chịu.</p><h2 id="_2-dich-vu-sap-thi-chi-biet-cho" tabindex="-1">2. Dịch vụ sập thì chỉ biết chờ <a class="header-anchor" href="#_2-dich-vu-sap-thi-chi-biet-cho" aria-label="Permalink to &quot;2. Dịch vụ sập thì chỉ biết chờ&quot;">​</a></h2><p>Khi AWS gặp sự cố ở một region, hàng nghìn công ty cùng sập theo, và việc duy nhất họ làm được là ngồi xem trang trạng thái của AWS. Tự host thì ít nhất bạn còn có thể tự lao vào sửa, còn ở đây bạn hoàn toàn bất lực.</p><h2 id="_3-kho-chan-đoan-khi-co-loi-hoac-cham" tabindex="-1">3. Khó chẩn đoán khi có lỗi hoặc chậm <a class="header-anchor" href="#_3-kho-chan-đoan-khi-co-loi-hoac-cham" aria-label="Permalink to &quot;3. Khó chẩn đoán khi có lỗi hoặc chậm&quot;">​</a></h2><p>Khi tự chạy phần mềm, bạn xem được mọi thứ: CPU, RAM, ổ đĩa, log của server, thậm chí debug sâu vào hệ điều hành để hiểu tại sao nó chậm. Với dịch vụ do nhà cung cấp vận hành, bạn thường không được nhìn vào bên trong.</p><p>Ví dụ: database cloud của bạn đột nhiên chậm vào 3 giờ chiều mỗi ngày. Có thể do bạn dùng sai cách, có thể do máy chủ bên dưới đang chia sẻ với khách hàng khác, có thể do họ đang chạy bảo trì. Bạn chỉ thấy vài chỉ số họ cho phép xem, nên đoán mò rất mệt.</p><h2 id="_4-bi-phu-thuoc-vao-nha-cung-cap-vendor-lock-in" tabindex="-1">4. Bị phụ thuộc vào nhà cung cấp (vendor lock-in) <a class="header-anchor" href="#_4-bi-phu-thuoc-vao-nha-cung-cap-vendor-lock-in" aria-label="Permalink to &quot;4. Bị phụ thuộc vào nhà cung cấp (vendor lock-in)&quot;">​</a></h2><p>Nếu nhà cung cấp đóng cửa dịch vụ, tăng giá quá cao, hoặc thay đổi sản phẩm theo hướng bạn không thích, bạn hoàn toàn phụ thuộc vào họ. Bạn không thể tiếp tục chạy phiên bản cũ, mà buộc phải chuyển sang dịch vụ khác.</p><p>Ví dụ thật: năm 2022 Heroku bỏ gói miễn phí, rất nhiều dự án phải chuyển đi trong vài tháng.</p><p>Rủi ro này nhẹ hơn nếu có dịch vụ thay thế dùng <strong>API tương thích</strong>. Ví dụ Amazon Aurora tương thích Postgres: nếu muốn rời AWS, code của bạn vẫn chạy được trên Postgres ở nơi khác mà gần như không phải sửa. Nhưng nếu bạn xây cả hệ thống trên DynamoDB, vốn có API riêng của AWS, thì muốn chuyển đi là phải viết lại toàn bộ tầng truy cập dữ liệu. Chi phí chuyển đổi cao như vậy chính là &quot;lock-in&quot;, bị khóa chặt vào một nhà cung cấp.</p><h2 id="_5-rui-ro-chinh-tri" tabindex="-1">5. Rủi ro chính trị <a class="header-anchor" href="#_5-rui-ro-chinh-tri" aria-label="Permalink to &quot;5. Rủi ro chính trị&quot;">​</a></h2><p>Nếu nhà cung cấp ở nước khác và hai nước xảy ra xung đột, bạn có thể bị cắt dịch vụ do lệnh trừng phạt. Ví dụ năm 2019, GitHub từng hạn chế tài khoản của người dùng ở một số khu vực bị Mỹ cấm vận, dù họ không làm gì sai. Với một doanh nghiệp, mất quyền truy cập vào hạ tầng chỉ sau một quyết định chính trị là rủi ro rất lớn.</p><h2 id="_6-phai-tin-tuong-nha-cung-cap-ve-bao-mat" tabindex="-1">6. Phải tin tưởng nhà cung cấp về bảo mật <a class="header-anchor" href="#_6-phai-tin-tuong-nha-cung-cap-ve-bao-mat" aria-label="Permalink to &quot;6. Phải tin tưởng nhà cung cấp về bảo mật&quot;">​</a></h2><p>Dữ liệu của bạn nằm trên máy của họ, nên bạn phải tin họ giữ an toàn. Việc này làm phức tạp chuyện tuân thủ luật. Ví dụ một ngân hàng ở một số nước bị yêu cầu dữ liệu khách hàng phải nằm trong lãnh thổ quốc gia, và phải chứng minh được ai có quyền truy cập. Khi dữ liệu nằm trên cloud, họ phải xác minh nhà cung cấp đáp ứng được các yêu cầu đó, chứ không tự kiểm soát hoàn toàn.</p><h2 id="ket-luan-cua-tac-gia" tabindex="-1">Kết luận của tác giả <a class="header-anchor" href="#ket-luan-cua-tac-gia" aria-label="Permalink to &quot;Kết luận của tác giả&quot;">​</a></h2><p>Dù có những rủi ro trên, ngày càng nhiều công ty vẫn xây ứng dụng mới trên cloud, hoặc dùng cách <strong>lai (hybrid)</strong>: một phần chạy cloud, một phần tự host.</p><p>Nhưng cloud sẽ không thay thế hoàn toàn hệ thống tự host, vì hai lý do. Thứ nhất, nhiều hệ thống cũ ra đời trước cả khi có cloud và vẫn đang chạy tốt. Thứ hai, có những yêu cầu đặc biệt mà cloud không đáp ứng được. Ví dụ giao dịch chứng khoán tần suất cao (high-frequency trading): chậm vài micro giây là thua đối thủ, nên các công ty này cần kiểm soát hoàn toàn phần cứng, thậm chí đặt máy chủ ngay cạnh sàn giao dịch để rút ngắn đường truyền mạng. Trên cloud, bạn không chọn được máy chủ nằm ở đâu hay chạy chung với ai, nên không đạt được mức kiểm soát đó.</p><h2 id="tom-lai-1" tabindex="-1">Tóm lại <a class="header-anchor" href="#tom-lai-1" aria-label="Permalink to &quot;Tóm lại&quot;">​</a></h2><p>Đoạn trước nói cloud tiết kiệm công sức và linh hoạt. Đoạn này nói cái giá phải trả: mất quyền kiểm soát, gồm không tự thêm tính năng được, không tự sửa khi sập, khó debug, bị khóa vào nhà cung cấp, và phụ thuộc vào chính trị cũng như cam kết bảo mật của họ. Lựa chọn đúng là cân giữa hai mặt này cho từng hệ thống cụ thể.</p>',41)])])}const d=h(o,[["render",g]]);export{p as __pageData,d as default};
